From 4211e834fd1c76475b959c6d9cef8cae32326d35 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 02:24:47 +0100
Subject: [PATCH] greeter: hold a prompt response that arrives before the
 prompt

Responses sent during the fail delay or while the worker was starting
were dropped, and cancel() kept the old prompt so they went to a dead
worker. Clear it on cancel and hold early responses for the next prompt.

BUG: 528356
---
 greeter/pamauthenticator.cpp | 27 ++++++++++++++++++---------
 greeter/pamauthenticator.h   |  3 +++
 2 files changed, 21 insertions(+), 9 deletions(-)

diff --git a/greeter/pamauthenticator.cpp b/greeter/pamauthenticator.cpp
index fe4b6e6e..69c84711 100644
--- a/greeter/pamauthenticator.cpp
+++ b/greeter/pamauthenticator.cpp
@@ -159,12 +159,16 @@ void PamAuthenticator::respond(const QByteArray &response)
         m_dbusWorker->connection().send(reply);
         m_pendingPrompt = {};
     } else {
-        qCWarning(KSCREENLOCKER_GREET) << "Received prompt response, but no pending prompt was found!";
+        // The worker is still starting or in the fail delay, answer its next prompt instead of losing the response
+        qCDebug(KSCREENLOCKER_GREET) << "Received prompt response before a prompt, holding it for the next one";
+        m_heldResponse = response;
     }
 }

 void PamAuthenticator::cancel()
 {
+    m_pendingPrompt = {};
+    m_heldResponse.reset();
     m_prompt.clear();
     m_promptForSecret.clear();
     m_infoMessage.clear();
@@ -278,23 +282,28 @@ QString PamAuthenticator::promptInternal(const QString &msg, bool isSecret)
 {
     setBusy(false);

-    if (isSecret) {
-        m_promptForSecret = msg;
-        Q_EMIT promptForSecret(msg);
-    } else {
-        m_prompt = msg;
-        Q_EMIT prompt(msg);
-    }
-
     qCDebug(KSCREENLOCKER_GREET,
             "[PAM worker %s] Message: %s: %s",
             qUtf8Printable(m_service),
             (isSecret ? "Echo-off prompt" : "Echo-on prompt"),
             qUtf8Printable(msg));

+    // Store the prompt before announcing it, so that it can be answered right away
     setDelayedReply(true);
     m_pendingPrompt = message();

+    if (isSecret) {
+        m_promptForSecret = msg;
+        Q_EMIT promptForSecret(msg);
+    } else {
+        m_prompt = msg;
+        Q_EMIT prompt(msg);
+    }
+
+    if (auto response = std::exchange(m_heldResponse, std::nullopt); response && m_pendingPrompt.type() != QDBusMessage::InvalidMessage) {
+        respond(*response);
+    }
+
     return {};
 }

diff --git a/greeter/pamauthenticator.h b/greeter/pamauthenticator.h
index 5dc19426..3d9e6e65 100644
--- a/greeter/pamauthenticator.h
+++ b/greeter/pamauthenticator.h
@@ -13,6 +13,7 @@
 #include <QDateTime>
 #include <QObject>
 #include <memory>
+#include <optional>
 #include <qqmlregistration.h>

 class QDBusPendingCallWatcher;
@@ -140,6 +141,8 @@ private:
     QDateTime m_lastFailed = QDateTime::currentDateTimeUtc();
     NoninteractiveAuthenticatorTypes m_authenticatorType;
     QDBusMessage m_pendingPrompt;
+    // A response that arrived while no prompt was pending, it answers the next one
+    std::optional<QByteArray> m_heldResponse;
     QDBusServer *m_server = nullptr;
     QDBusPendingCallWatcher *m_authenticateWatcher = nullptr;
     std::unique_ptr<OrgKdePlasmaScreenlockerWorkerInterface> m_dbusWorker;
-- 
2.53.0

From 0dbcadb8a26c93342c2903250728e5d066e89c40 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 02:24:47 +0100
Subject: [PATCH] lockscreen: clear the password on submit and ignore empty
 ones

Keys typed while a password was checked were lost as focus sat on the
unlock button, an empty Enter counted as a failed login and pamTimeout
never existed. Clear the field on submit and skip empty passwords.

BUG: 528356
---
 .../contents/lockscreen/LockScreenUi.qml      | 28 ++++++-------------
 1 file changed, 9 insertions(+), 19 deletions(-)

diff --git a/desktoppackage/contents/lockscreen/LockScreenUi.qml b/desktoppackage/contents/lockscreen/LockScreenUi.qml
index e62546a54a..7618ed6d61 100644
--- a/desktoppackage/contents/lockscreen/LockScreenUi.qml
+++ b/desktoppackage/contents/lockscreen/LockScreenUi.qml
@@ -51,8 +51,6 @@ Item {
         lockScreenRoot.uiVisible = true
     }

-    property string pendingPassword
-
     Kirigami.Theme.inherit: false
     Kirigami.Theme.colorSet: Kirigami.Theme.Complementary

@@ -64,7 +62,8 @@ Item {
             }
             const msg = i18ndc("plasma_shell_org.kde.plasma.desktop", "@info:status", "Unlocking failed");
             lockScreenUi.handleMessage(msg);
-            root.clearPassword();
+            // The field was cleared on submit, keep a retry that is already being typed
+            mainBlock.mainPasswordBox.forceActiveFocus();
             authenticator.startAuthenticating();
             notificationRemoveTimer.restart();
             rejectPasswordAnimation.start();
@@ -291,17 +290,6 @@ Item {
             }
         }

-        Connections {
-            target: authenticator
-            function onPamTimeoutChanged(): void {
-                if (!authenticator.pamTimeout && lockScreenUi.pendingPassword.length > 0) {
-                    authenticator.respond(lockScreenUi.pendingPassword);
-                    lockScreenUi.pendingPassword = "";
-                    mainBlock.enabled = true;
-                }
-            }
-        }
-
         StackView {
             id: mainStack
             anchors {
@@ -401,12 +389,14 @@ Item {
                 }

                 onPasswordResult: password => {
-                    if (authenticator.pamTimeout) {
-                        lockScreenUi.pendingPassword = password
-                        mainBlock.enabled = false
-                    } else {
-                        authenticator.respond(password)
+                    // Clear the field right away, so that keys typed while the result is pending
+                    // start a new password instead of being lost or added to the old one
+                    root.clearPassword();
+                    // Enter on an empty field, e.g. to wake the screen, is not an unlock attempt
+                    if (password.length === 0) {
+                        return;
                     }
+                    authenticator.respond(password);
                 }

                 actionItems: [
-- 
